begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select format('a2070000-0000-4000-8000-%s',lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','consent207-'||i||'@example.invalid','',case when i=1 then now()else null end,'{}','{}',now(),now()from generate_series(1,2)i;
select ok(not has_function_privilege('authenticated','public.register_legal_consent_documents_v1(text,text,text,jsonb)','EXECUTE')and not has_function_privilege('anon','public.accept_account_legal_consent_v1(uuid,text,boolean,text)','EXECUTE'),'only the trusted server registers exact texts and only authenticated users can accept');
select ok(not has_table_privilege('authenticated','public.account_legal_consent_acceptances','INSERT')and not has_table_privilege('authenticated','public.legal_consent_document_sets','UPDATE'),'app actors cannot fabricate proofs or rewrite the text registry');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('test.legal_set_one',public.register_legal_consent_documents_v1('2090-01-01','2090-01-01','fr','{"terms":{"title":"Conditions de recette"},"privacy":{"title":"Confidentialité de recette"}}')::text,true);
select lives_ok($$select public.register_legal_consent_documents_v1('2090-01-01','2090-01-01','fr','{"privacy":{"title":"Confidentialité de recette"},"terms":{"title":"Conditions de recette"}}')$$,'same exact text replays despite object key order');
select throws_ok($$select public.register_legal_consent_documents_v1('2090-01-01','2090-01-01','fr','{"terms":{"title":"Modification silencieuse"},"privacy":{}}')$$,'22000','LEGAL_TEXT_VERSION_COLLISION','text cannot change under an already recorded version');
select set_config('request.jwt.claims','{"sub":"a2070000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,true,%L)',current_setting('test.legal_set_one')::jsonb->>'id',current_setting('test.legal_set_one')::jsonb->>'source_hash','no-email-207'),'42501','VERIFIED_LEGAL_ACTOR_REQUIRED','missing verified email claim cannot create legal acceptance');
select set_config('request.jwt.claims','{"sub":"a2070000-0000-4000-8000-000000000002","email":"consent207-2@example.invalid","role":"authenticated","aal":"aal1"}',true);
select throws_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,true,%L)',current_setting('test.legal_set_one')::jsonb->>'id',current_setting('test.legal_set_one')::jsonb->>'source_hash','unverified-email-207'),'42501','VERIFIED_LEGAL_ACTOR_REQUIRED','unverified actor cannot create legal acceptance');
select set_config('request.jwt.claims','{"sub":"a2070000-0000-4000-8000-000000000001","email":"consent207-1@example.invalid","role":"authenticated","aal":"aal1"}',true);
select throws_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,false,%L)',current_setting('test.legal_set_one')::jsonb->>'id',current_setting('test.legal_set_one')::jsonb->>'source_hash','unchecked-consent-207'),'22023','EXPLICIT_LEGAL_CONSENT_REQUIRED','an unchecked box cannot create acceptance');
select throws_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,true,%L)',current_setting('test.legal_set_one')::jsonb->>'id',repeat('f',64),'wrong-hash-207'),'22000','LEGAL_TEXT_HASH_MISMATCH','a browser cannot substitute a text hash');
select lives_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,true,%L)',current_setting('test.legal_set_one')::jsonb->>'id',current_setting('test.legal_set_one')::jsonb->>'source_hash','accept-one-207'),'verified user without any workspace role can explicitly accept current texts');
select lives_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,true,%L)',current_setting('test.legal_set_one')::jsonb->>'id',current_setting('test.legal_set_one')::jsonb->>'source_hash','accept-one-207'),'same acceptance command is idempotent');
select is((select count(*)::integer from public.account_legal_consent_acceptances where user_id='a2070000-0000-4000-8000-000000000001'),1,'replay creates one immutable proof');
select is((select count(*)::integer from public.audit_events where actor_user_id='a2070000-0000-4000-8000-000000000001'and action='account.legal_consent.accepted'),1,'one acceptance has one audit record');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('test.legal_set_two',public.register_legal_consent_documents_v1('2090-02-01','2090-02-01','fr','{"terms":{"title":"Nouvelles conditions de recette"},"privacy":{"title":"Nouvelle confidentialité de recette"}}')::text,true);
select throws_ok($$select public.register_legal_consent_documents_v1('2090-01-01','2090-01-01','fr','{"terms":{},"privacy":{}}')$$,'55000','LEGAL_DOCUMENT_VERSION_OUTDATED','an older application server cannot restore an older applicable text set');
select set_config('request.jwt.claims','{"sub":"a2070000-0000-4000-8000-000000000001","email":"consent207-1@example.invalid","role":"authenticated","aal":"aal1"}',true);
select ok(public.get_my_legal_consent_v1('fr')#>>'{current,accepted_at}'is null,'new version is visibly proposed until explicitly accepted');
select throws_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,true,%L)',current_setting('test.legal_set_one')::jsonb->>'id',current_setting('test.legal_set_one')::jsonb->>'source_hash','accept-obsolete-207'),'55000','LEGAL_DOCUMENT_VERSION_OUTDATED','an obsolete form cannot accept a superseded version');
select throws_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,true,%L)',current_setting('test.legal_set_two')::jsonb->>'id',current_setting('test.legal_set_two')::jsonb->>'source_hash','accept-one-207'),'22000','LEGAL_CONSENT_IDEMPOTENCY_MISMATCH','an old command key cannot silently switch to new texts');
select lives_ok(format('select public.accept_account_legal_consent_v1(%L::uuid,%L,true,%L)',current_setting('test.legal_set_two')::jsonb->>'id',current_setting('test.legal_set_two')::jsonb->>'source_hash','accept-two-207'),'new text version appends a distinct consent proof');
select is(jsonb_array_length(public.get_my_legal_consent_v1('fr')->'history'),2,'the same actor can retrieve both exact historical versions');
select throws_ok($$update public.account_legal_consent_acceptances set source_hash=repeat('f',64)where user_id='a2070000-0000-4000-8000-000000000001'$$,'55000',null,'historical acceptance cannot be rewritten');
select set_config('request.jwt.claims','{"sub":"a2070000-0000-4000-8000-000000000002","email":"consent207-2@example.invalid","role":"authenticated","aal":"aal1"}',true);
select is(jsonb_array_length(public.get_my_legal_consent_v1('fr')->'history'),0,'another actor cannot read the first actors consent history');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('test.registration_receipt207',public.reserve_registration_consent('consent207-2@example.invalid','fr','2090-02-01','2090-02-01')::text,true);
select is((select document_set_id::text from public.registration_consent_receipts where id=current_setting('test.registration_receipt207')::uuid),current_setting('test.legal_set_two')::jsonb->>'id','new registration receipt points to the exact immutable text snapshot');
update auth.users set email_confirmed_at=clock_timestamp()where id='a2070000-0000-4000-8000-000000000002';
select set_config('request.jwt.claims','{"sub":"a2070000-0000-4000-8000-000000000002","email":"consent207-2@example.invalid","role":"authenticated","aal":"aal1"}',true);
select lives_ok(format('select public.confirm_registration_consent(%L::uuid)',current_setting('test.registration_receipt207')),'new confirmed registration creates its original versioned proof');
select ok(public.get_my_legal_consent_v1('fr')#>>'{current,accepted_at}'is not null,'same current initial registration consent is recognized without asking again');
select is(public.get_my_legal_consent_v1('fr')#>>'{history,0,source_type}','REGISTRATION','own initial proof and its exact text are readable in the same history');
select * from finish();
rollback;
